#include <stdexcept>
#include <cstring>

class Matrix {
private:
    double* data_;
    int rows_;
    int cols_;

    void validate(int r, int c) const {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Matrix index out of range");
        }
    }

    void copyFrom(const Matrix& other) {
        rows_ = other.rows_;
        cols_ = other.cols_;
        data_ = new double[rows_ * cols_];
        std::memcpy(data_, other.data_, rows_ * cols_ * sizeof(double));
    }

    void swap(Matrix& other) noexcept {
        std::swap(data_, other.data_);
        std::swap(rows_, other.rows_);
        std::swap(cols_, other.cols_);
    }

public:
    Matrix(int rows, int cols) : data_(nullptr), rows_(0), cols_(0) {
        if (rows <= 0 || cols <= 0) {
            throw std::invalid_argument("Rows and columns must be positive");
        }
        rows_ = rows;
        cols_ = cols;
        data_ = new double[rows_ * cols_];
        std::memset(data_, 0, rows_ * cols_ * sizeof(double));
    }

    ~Matrix() {
        delete[] data_;
    }

    Matrix(const Matrix& other) {
        copyFrom(other);
    }

    Matrix(Matrix&& other) noexcept : data_(other.data_), rows_(other.rows_), cols_(other.cols_) {
        other.data_ = nullptr;
        other.rows_ = 0;
        other.cols_ = 0;
    }

    Matrix& operator=(const Matrix& other) {
        if (this != &other) {
            double* newData = nullptr;
            int newRows = other.rows_;
            int newCols = other.cols_;
            newData = new double[newRows * newCols];
            std::memcpy(newData, other.data_, newRows * newCols * sizeof(double));
            delete[] data_;
            data_ = newData;
            rows_ = newRows;
            cols_ = newCols;
        }
        return *this;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            other.data_ = nullptr;
            other.rows_ = 0;
            other.cols_ = 0;
        }
        return *this;
    }

    double& at(int r, int c) {
        validate(r, c);
        return data_[r * cols_ + c];
    }

    double at(int r, int c) const {
        validate(r, c);
        return data_[r * cols_ + c];
    }

    int rows() const {
        return rows_;
    }

    int cols() const {
        return cols_;
    }

    Matrix operator+(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            throw std::invalid_argument("Matrix dimensions must match for addition");
        }
        Matrix result(rows_, cols_);
        for (int i = 0; i < rows_ * cols_; ++i) {
            result.data_[i] = data_[i] + o.data_[i];
        }
        return result;
    }

    Matrix operator*(const Matrix& o) const {
        if (cols_ != o.rows_) {
            throw std::invalid_argument("Matrix dimensions mismatch for multiplication");
        }
        Matrix result(rows_, o.cols_);
        for (int i = 0; i < rows_; ++i) {
            for (int j = 0; j < o.cols_; ++j) {
                double sum = 0.0;
                for (int k = 0; k < cols_; ++k) {
                    sum += data_[i * cols_ + k] * o.data_[k * o.cols_ + j];
                }
                result.data_[i * o.cols_ + j] = sum;
            }
        }
        return result;
    }

    bool operator==(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            return false;
        }
        for (int i = 0; i < rows_ * cols_; ++i) {
            if (data_[i] != o.data_[i]) {
                return false;
            }
        }
        return true;
    }
};
