import java.time.LocalDate;
import java.util.*;

public class Library {

    private static class Book {
        String isbn;
        String title;
        String borrower;
        LocalDate borrowDate;

        Book(String isbn, String title) {
            this.isbn = isbn;
            this.title = title;
            this.borrower = null;
            this.borrowDate = null;
        }

        boolean isBorrowed() {
            return borrower != null;
        }
    }

    private final Map<String, Book> booksByIsbn = new HashMap<>();
    private final Map<String, Book> booksByTitle = new HashMap<>();

    public void addBook(String isbn, String title) {
        if (isbn == null || title == null) {
            throw new IllegalArgumentException("ISBN and title must not be null");
        }
        if (booksByIsbn.containsKey(isbn)) {
            throw new IllegalArgumentException("ISBN already exists: " + isbn);
        }
        Book book = new Book(isbn, title);
        booksByIsbn.put(isbn, book);
        booksByTitle.put(title, book);
    }

    public void borrow(String isbn, String member, LocalDate date) {
        if (isbn == null || member == null || date == null) {
            throw new IllegalArgumentException("Parameters must not be null");
        }
        Book book = booksByIsbn.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("ISBN not found: " + isbn);
        }
        if (book.isBorrowed()) {
            throw new IllegalStateException("Book already borrowed: " + isbn);
        }
        book.borrower = member;
        book.borrowDate = date;
    }

    public void giveBack(String isbn) {
        if (isbn == null) {
            throw new IllegalArgumentException("ISBN must not be null");
        }
        Book book = booksByIsbn.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("ISBN not found: " + isbn);
        }
        if (!book.isBorrowed()) {
            throw new IllegalStateException("Book not currently borrowed: " + isbn);
        }
        book.borrower = null;
        book.borrowDate = null;
    }

    public List<String> overdue(LocalDate today, int days) {
        if (today == null) {
            throw new IllegalArgumentException("today must not be null");
        }
        List<String> result = new ArrayList<>();
        for (Book book : booksByIsbn.values()) {
            if (book.isBorrowed() && book.borrowDate != null) {
                long daysBorrowed = LocalDate.between(book.borrowDate, today).toDays();
                if (daysBorrowed > days) {
                    result.add(book.title);
                }
            }
        }
        Collections.sort(result);
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> loans = new HashMap<>();
        for (Book book : booksByIsbn.values()) {
            if (book.isBorrowed() && book.borrower != null) {
                loans.merge(book.borrower, 1, Integer::sum);
            }
        }
        return loans;
    }
}
